// Generated by test-gen (standard) from docs/implementations/017-transaction-details-wiring-fe.md §FE-4. Regenerate: /test-gen standard.
//
// NOTE on pre-implementation state: FE-4 adds mode/details/loading props to
// TransactionDetailModal — none exist yet, so every mode="view" assertion
// below fails (the component always renders the editable form) as the
// correct pre-implementation signal.
import { beforeEach, describe, expect, it, vi } from "vitest";
import { screen } from "@testing-library/react";
import { renderWithAuth as render } from "@/tests/_helpers/renderWithAuth";
import { TransactionDetailModal } from "@/components/rm/TransactionDetailModal";
import type { TransactionDetailDTO } from "@/lib/onboarding/types";

const DETAILS: TransactionDetailDTO = {
  id: "td-1", allotment_id: "a-1", bank_account: "HSBC-4471-001",
  settlement_amount: 180_000, transaction_date: "2026-08-01", transaction_time: "14:30",
  currency: "USD", reference_no: "TXN-1", filed_by: "rm-uid", filed_at: "2026-08-01T14:31:00Z",
};

// Modal portals into #content-overlay-root (components/rm/Shared.tsx) — without
// this element in the DOM, Modal's `if (!root) return null` guard makes every
// render() a no-op, per the FE-6.subscriptions.test.tsx precedent.
beforeEach(() => {
  document.body.innerHTML = '<div id="content-overlay-root"></div>';
});

describe("FE-4 mode='edit' (or omitted) renders identically to the pre-existing modal", () => {
  it("shows 6 editable fields and a Save button disabled until the 4 required fields are filled", () => {
    render(
      <TransactionDetailModal type="Allotment" clientName="Ardent Capital" modelName="Model A" rawAmount="180,000" onClose={vi.fn()} onSave={vi.fn()} />,
    );
    expect(screen.getByPlaceholderText("e.g. HSBC-4471-001")).toBeInTheDocument();
    expect(screen.getByPlaceholderText("e.g. TXN-20260301-001")).toBeInTheDocument();
    expect(screen.getByRole("button", { name: /save/i })).toBeDisabled();
  });

  it("mode omitted behaves the same as mode='edit' explicitly", () => {
    render(
      <TransactionDetailModal type="Redemption" clientName="Vela Holdings" modelName="Equity Growth" rawAmount="80,000" onClose={vi.fn()} onSave={vi.fn()} mode="edit" />,
    );
    expect(screen.getByRole("button", { name: /save/i })).toBeInTheDocument();
    // Modal's header dismiss button is icon-only with aria-label="Close" (Shared.tsx),
    // so it also matches a role+name query — scope to visible text instead, which the
    // header button has none of, to check only the footer for a "Close" button.
    expect(screen.queryByText("Close")).not.toBeInTheDocument();
  });
});

describe("FE-4 mode='view' with populated details renders read-only text + Close only", () => {
  it("shows all 6 values as plain text, no input/select present, and a single Close button", () => {
    render(
      <TransactionDetailModal
        type="Allotment" clientName="Ardent Capital" modelName="Model A" rawAmount="180,000"
        mode="view" details={DETAILS} onClose={vi.fn()} onSave={vi.fn()}
      />,
    );
    expect(screen.getByText("HSBC-4471-001")).toBeInTheDocument();
    expect(screen.getByText("2026-08-01")).toBeInTheDocument();
    expect(screen.getByText("14:30")).toBeInTheDocument();
    expect(screen.getByText("USD")).toBeInTheDocument();
    expect(screen.getByText("TXN-1")).toBeInTheDocument();
    expect(document.querySelector("input")).not.toBeInTheDocument();
    expect(document.querySelector("select")).not.toBeInTheDocument();
    // Scope to visible text, not role+name — Modal's icon-only header dismiss button
    // also has aria-label="Close" and would otherwise make this query ambiguous.
    expect(screen.getByText("Close")).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: /^save$/i })).not.toBeInTheDocument();
  });

  it("a null/absent reference_no renders as an em dash, not blank", () => {
    render(
      <TransactionDetailModal
        type="Allotment" clientName="Ardent Capital" modelName="Model A" rawAmount="180,000"
        mode="view" details={{ ...DETAILS, reference_no: null }} onClose={vi.fn()} onSave={vi.fn()}
      />,
    );
    expect(screen.getByText("—")).toBeInTheDocument();
  });
});

describe("FE-4 mode='view' with loading=true shows the loading message, not the field grid", () => {
  it("renders none of the 6 fields while loading", () => {
    render(
      <TransactionDetailModal
        type="Allotment" clientName="Ardent Capital" modelName="Model A" rawAmount="180,000"
        mode="view" details={null} loading onClose={vi.fn()} onSave={vi.fn()}
      />,
    );
    expect(screen.getByText(/loading transaction details/i)).toBeInTheDocument();
    expect(screen.queryByText("HSBC-4471-001")).not.toBeInTheDocument();
  });
});
